with zipfile.ZipFile('/filesystem/final_batch4__structural_task6_seismic_diaphragm_shear__blind/output/submission.zip', 'r') as zf:
    for sheet in ['WEIGHTS', 'BASE_SHEAR', 'DIAPHRAGM_FORCES', 'WALL_FORCES', 'PARAPET_ANCHORAGE', 'CHORD_FORCES']:
        if sheet in zf.namelist():
            print(f'{sheet} found in zip namelist')
            data = zf.read(sheet)
            wb = openpyxl.load_workbook(io.BytesIO(data))
            print(f'  Sheets: {wb.sheetnames}')
            if sheet in wb.sheetnames:
                ws = wb[sheet]
                print(f'  {sheet}: {ws.max_row} rows x {ws.max_column} cols')
            else:
                # Try to find it
                for sname in wb.sheetnames:
                    print(f'  Found sheet: {sname}')
        else:
            print(f'{sheet} NOT in zip namelist')
            # List all files in zip
            print('  Zip contents:')
            for n in zf.namelist():
                print(f'   {n}')
